package com.eatwhat.service;
import com.eatwhat.entity.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class DietReportFoundationTest {
 RecipeRecord record(long id,String date){RecipeRecord r=new RecipeRecord();r.setId(id);r.setUserId(1L);r.setRecordDateString(date);r.setMealType("dinner");r.setRecipeName("面");r.setRevision(1L);return r;}
 Map<String,Object> report(long user,List<RecipeRecord> records){return new DietReviewCalculator(new ObjectMapper()).report(user,Collections.emptyList(),records,LocalDate.parse("2026-01-01"),LocalDate.parse("2026-01-07"),Instant.parse("2026-01-03T04:00:00Z"));}
 Map<?,?> metadata(Map<String,Object> r){return (Map<?,?>)r.get("metadata");}
 @Test void sourceIdentityIsOrderIndependentAndChangesOnRevisionOrAccount(){RecipeRecord a=record(1,"2026-01-01"),b=record(2,"2026-01-02");Object first=metadata(report(1,Arrays.asList(a,b))).get("reportId");assertEquals(first,metadata(report(1,Arrays.asList(b,a))).get("reportId"));a.setRevision(2L);assertNotEquals(first,metadata(report(1,Arrays.asList(a,b))).get("reportId"));assertNotEquals(metadata(report(1,Arrays.asList(a,b))).get("reportId"),metadata(report(2,Arrays.asList(a,b))).get("reportId"));}
 @Test void reportHasOnlyRecordBlocksAndTraceableTargets(){Map<String,Object> report=report(1,Arrays.asList(record(1,"2026-01-01"),record(2,"2026-01-05")));assertEquals("calendar_records",metadata(report).get("basis"));assertEquals("calendar-records-v1",metadata(report).get("calculationVersion"));Map<?,?> blocks=(Map<?,?>)report.get("blocks");assertEquals(5,blocks.size());assertFalse(blocks.containsKey("planExecution"));Map<?,?> row=(Map<?,?>)((List<?>)((Map<?,?>)blocks.get("actualDetails")).get("records")).get(0);assertEquals("/pages/calendar-detail/calendar-detail?date=2026-01-01&mealType=dinner",row.get("sourceUrl"));assertEquals("recorded",row.get("status"));assertEquals(1,report.get("mealCount"));}
}
